/*
   PLEASE NOTE
   THIS MACRO IS NOT OFFICIALLY PART OF THE SYSTEM AND HAS NOT BEEN CLEANED UP OR CHECKED.
   IT HAS BEEN INCLUDED FOR YOUR EASE.
   USE AT YOUR OWN RISK.
*/

const I_WANT_TRANSFORM_TO_ALSO_COPY_SKILLS_BASESTATS_AND_PROPER_SIZE = false

let didSomething = false
if (game.canvas.tokens.controlled.length == 0){
  return ui.notifications.error("Select token(s) to (un)transform");
}


for (const transformerToken of game.canvas.tokens.controlled){
  const TRANSFORMER = transformerToken.actor
  TRANSFORMER.items.filter(i => i.type=="effect" && i.name.startsWith("Transformed into ")).forEach( e => {

    //console.log(e)
    e.delete()
    didSomething = true
  })
}


const TRANSFORMEE_TOKEN = game.user.targets.first()
if (! TRANSFORMEE_TOKEN) {
  if(didSomething){
        return ui.notifications.info("Untransformed")
  } else {
        return ui.notifications.error("Select a target to transform into");
  }
}

const ORIGINAL_ITEMS = TRANSFORMEE_TOKEN.actor.items.filter(i => i.type=="move" || i.type=="ability" || i.type=="capability")


for (const transformerToken of game.canvas.tokens.controlled){
  const TRANSFORMER = transformerToken.actor
  let effectRules = []

  let scale = TRANSFORMEE_TOKEN.document.texture.scaleX
  if (I_WANT_TRANSFORM_TO_ALSO_COPY_SKILLS_BASESTATS_AND_PROPER_SIZE) {
    scale = scale * TRANSFORMEE_TOKEN.document.width
  }

  effectRules.push({
    key:"TokenImage",
    value: TRANSFORMEE_TOKEN.document.texture.src, 
    scale: scale
  })

  effectRules.push({
    key:"TypeOverwrite",
    value: TRANSFORMEE_TOKEN.actor.system.typing
  })

  if (! I_WANT_TRANSFORM_TO_ALSO_COPY_SKILLS_BASESTATS_AND_PROPER_SIZE) {
      effectRules.push({
        key:"TemporarySpecies",
        uuid: TRANSFORMEE_TOKEN.actor.items.filter(i => i.type == "species")[0].uuid
      })
  }

  for (const item of ORIGINAL_ITEMS){
    effectRules.push({
      key: "GrantItem",
      reevaluateOnUpdate: false,
      allowDuplicate: false,
      predicate: [],
      uuid: item.uuid
    })
  }

  for (const capName of ["overland","sky","swim","levitate","burrow","highJump","longJump","power"]){
    const cap = TRANSFORMEE_TOKEN.actor.system.capabilities[capName]
    const capDitto = TRANSFORMER.system.capabilities[capName]
    effectRules.push({
      key: "ActiveEffectLike",
      mode: "add",
      predicate: [],
      phase: "applyAEs",
      path: `system.modifiers.capabilities.${capName}`,
      value: `${cap} - ${capDitto}`
    })
  }


  // let eff = (await Item.create([{
  //   name: `Transform into ${TRANSFORMEE_TOKEN.name}`,
  //   img: TRANSFORMEE_TOKEN.document.texture.src, 
  //   type:"effect",
  //   system:{
  //     rules: effectRules
  //   }
  // }], {parent: TRANSFORMER}))[0]
  // 
  // const source = eff.toObject();
  // source.flags = mergeObject(source.flags ?? {}, { core: { sourceId: eff.uuid } });
  // 

  await TRANSFORMER.createEmbeddedDocuments("Item", [{
    name: `Transformed into ${TRANSFORMEE_TOKEN.name}`,
    img: TRANSFORMEE_TOKEN.document.texture.src, 
    type:"effect",
    system:{
      rules: effectRules
    }
  }]);

}

